package nir.com.neonvegasslots;import static org.junit.Assert.*;import android.graphics.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=34)public class GameFontsTest{@Test @Config(sdk=24) public void olderAndroidLoadsStaticFontFallback(){assertNotNull(GameFonts.display(RuntimeEnvironment.getApplication()));assertNotNull(GameFonts.body(RuntimeEnvironment.getApplication()));}@Test public void fontsAreBundledAndApplied()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();assertTrue(c.getAssets().open("fonts/fredoka.ttf").available()>10000);assertTrue(c.getAssets().open("fonts/nunito.ttf").available()>10000);LinearLayout l=new LinearLayout(c);TextView b=new TextView(c);Button h=new Button(c);l.addView(b);l.addView(h);GameFonts.apply(l);assertSame(GameFonts.body(c),b.getTypeface());assertSame(GameFonts.display(c),h.getTypeface());}}
